import org.apache.commons.cli.OptionBuilder;
import org.junit.jupiter.api.*;

import java.lang.reflect.Field;
import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.*;

public class OptionBuilderIsRequiredTest {

    private static Method resetMethod;
    private static Field requiredField;
    private static Field instanceField;
    private static Method isRequiredBoolMethod;

    @BeforeAll
    static void initReflection() throws Exception {
        Class<?> cls = OptionBuilder.class;

        // private static void reset()
        resetMethod = cls.getDeclaredMethod("reset");
        resetMethod.setAccessible(true);

        // private static boolean required
        requiredField = cls.getDeclaredField("required");
        requiredField.setAccessible(true);

        // private static final OptionBuilder INSTANCE
        instanceField = cls.getDeclaredField("INSTANCE");
        instanceField.setAccessible(true);

        // public static OptionBuilder isRequired(boolean)
        isRequiredBoolMethod = cls.getMethod("isRequired", boolean.class);
    }

    @BeforeEach
    void resetBefore() throws Exception {
        // ensure a clean state before each test
        resetMethod.invoke(null);
    }

    @AfterEach
    void resetAfter() throws Exception {
        // restore original state after each test
        resetMethod.invoke(null);
    }

    @Test
    void testIsRequiredSetsRequiredTrueAndReturnsSingleton() throws Exception {
        // ensure required is false to start
        isRequiredBoolMethod.invoke(null, false);
        assertFalse(requiredField.getBoolean(null), "Precondition: required should be false");

        // call focal method
        OptionBuilder returned = OptionBuilder.isRequired();

        // returned instance should be the private INSTANCE
        Object instance = instanceField.get(null);
        assertNotNull(returned, "Returned OptionBuilder should not be null");
        assertSame(instance, returned, "isRequired() should return the singleton INSTANCE");

        // required flag should be set to true
        assertTrue(requiredField.getBoolean(null), "required should be true after calling isRequired()");
    }

    @Test
    void testIsRequiredIsIdempotentAndResetsCorrectly() throws Exception {
        // Set required to false then call isRequired() multiple times
        isRequiredBoolMethod.invoke(null, false);
        assertFalse(requiredField.getBoolean(null), "Precondition: required should be false");

        OptionBuilder first = OptionBuilder.isRequired();
        OptionBuilder second = OptionBuilder.isRequired();

        // both calls return the same singleton instance
        assertSame(first, second, "Multiple calls to isRequired() should return the same instance");
        assertSame(instanceField.get(null), first, "Returned object should be the private INSTANCE field");
        assertTrue(requiredField.getBoolean(null), "required should be true after calls");

        // toggle required back to false and verify isRequired() sets it true again
        isRequiredBoolMethod.invoke(null, false);
        assertFalse(requiredField.getBoolean(null), "required should be false after toggling with isRequired(false)");

        OptionBuilder third = OptionBuilder.isRequired();
        assertSame(instanceField.get(null), third, "Returned object should still be the singleton INSTANCE after toggling");
        assertTrue(requiredField.getBoolean(null), "required should be true after calling isRequired() again");
    }
}

